ALTER TABLE "WORKSPACES" ADD COLUMN "invite_code" varchar(36);
UPDATE "WORKSPACES" SET "invite_code" = md5("id"::text) WHERE "invite_code" IS NULL;
ALTER TABLE "WORKSPACES" ALTER COLUMN "invite_code" SET NOT NULL;
CREATE UNIQUE INDEX "WORKSPACES_invite_code_key" ON "WORKSPACES"("invite_code");
CREATE TYPE "WORKSPACE_JOIN_REQUEST_STATUS" AS ENUM ('pending', 'approved', 'rejected');
CREATE TABLE "WORKSPACE_JOIN_REQUEST" ("id" uuid PRIMARY KEY,"workspace_id" uuid NOT NULL,"requester_id" uuid NOT NULL,"reviewer_id" uuid,"role_id" uuid,"status" "WORKSPACE_JOIN_REQUEST_STATUS" NOT NULL DEFAULT 'pending',"created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"responded_at" timestamptz);
ALTER TABLE "WORKSPACE_JOIN_REQUEST" ADD FOREIGN KEY ("workspace_id") REFERENCES "WORKSPACES"("id") ON DELETE RESTRICT;
ALTER TABLE "WORKSPACE_JOIN_REQUEST" ADD FOREIGN KEY ("requester_id") REFERENCES "USERS"("id") ON DELETE RESTRICT;
ALTER TABLE "WORKSPACE_JOIN_REQUEST" ADD FOREIGN KEY ("reviewer_id") REFERENCES "USERS"("id") ON DELETE SET NULL;
ALTER TABLE "WORKSPACE_JOIN_REQUEST" ADD FOREIGN KEY ("role_id") REFERENCES "ROLE"("id") ON DELETE RESTRICT;
CREATE INDEX "WORKSPACE_JOIN_REQUEST_workspace_id_status_idx" ON "WORKSPACE_JOIN_REQUEST"("workspace_id","status");
CREATE INDEX "WORKSPACE_JOIN_REQUEST_requester_id_status_idx" ON "WORKSPACE_JOIN_REQUEST"("requester_id","status");
